import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.BFmCivy-.js";const p=JSON.parse('{"title":"RLGW AI/ML Architecture & Anomaly Detection","description":"","frontmatter":{},"headers":[],"relativePath":"ml.md","filePath":"ml.md"}'),r={name:"ml.md"};function o(s,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="rlgw-ai-ml-architecture-anomaly-detection" tabindex="-1">RLGW AI/ML Architecture &amp; Anomaly Detection <a class="header-anchor" href="#rlgw-ai-ml-architecture-anomaly-detection" aria-label="Permalink to &quot;RLGW AI/ML Architecture &amp; Anomaly Detection&quot;">​</a></h1><p>This document specifies the dual-tier AI/ML architecture implemented in the Rate-Limit Gateway:</p><ul><li><strong>Tier A (Local, Real-Time)</strong>: In-process feature extraction and Isolation Forest abuse classifier written in pure TypeScript.</li><li><strong>Tier B (Offline/Forensic)</strong>: LLM incident diagnostic context builder, injection-hardened prompt engine, and schema validator for explaining security events.</li></ul><hr><h2 id="_1-safety-guarantees" tabindex="-1">1. Safety Guarantees <a class="header-anchor" href="#_1-safety-guarantees" aria-label="Permalink to &quot;1. Safety Guarantees&quot;">​</a></h2><ol><li><strong>Local-First &amp; Zero Leakage</strong>: All Tier A feature extraction and inference runs purely locally within Node.js. Raw client IPs, tokens, and authorization credentials are salted and pseudonymized using HMAC-SHA-256 before model ingestion.</li><li><strong>Deterministic Reproducibility</strong>: The Isolation Forest uses a deterministic seeded pseudo-random number generator (PRNG). Given the same seed and training dataset, the resulting decision trees and anomaly scores are 100% byte-for-byte reproducible.</li><li><strong>Bounded Overhead</strong>: Inference runs via a worker queue with bounded capacity (<code>drop_oldest</code> policy) ensuring zero blocking impact on hot data-plane rate limiting decisions.</li><li><strong>Advisory Role</strong>: The LLM forensic assistant can only explain what happened and propose actions to human operators; it cannot unilaterally mutate policies or apply bans.</li></ol>',6)])])}const h=t(r,[["render",o]]);export{p as __pageData,h as default};
